18	)
19	
20	// Config supplies the shared command options and the assembly package's
21	// storage and hosted-sync operations. Dependencies are per invocation, never
22	// global hooks.
23	type Config struct {
24		base.Options
25		Deps Deps
26	}
27	
28	// Deps keeps the connect command independent of command assembly, repo
29	// identity resolution, and the hosted sync engine. The assembly package
30	// supplies these operations so connect drives the same sync loop and push-hook
31	// management as the background triggers.
32	type Deps struct {
33		RepoStoragePaths   func(context.Context, base.CommandRunner, base.EntireEnv, string) (base.RepoStorage, error)
34		AgentSurfaceTarget func(base.Options, []string) string
35		// InstallPushHook installs the pre-push upload hook; sharedHooksDir
36		// reports a core.hooksPath shared across repos, where the hook is not
37		// managed.
38		InstallPushHook func(ctx context.Context, opts base.Options, repoDir string) (sharedHooksDir bool, hookPath string, err error)
39		// HostedFactsSyncAndPull runs one hosted sync for the branch; attempted
40		// reports whether the gates passed and the server was contacted,
41		// pullSucceeded whether the pull half completed.
42		HostedFactsSyncAndPull func(ctx context.Context, errW io.Writer, opts base.Options, repoDir string, storage base.RepoStorage, branch string) (attempted, pullSucceeded bool, err error)
43		HostedSyncBranch       func(context.Context, base.CommandRunner, string) string
44	}
45	
46	// minHostCLIVersion is the first host CLI release that ships `entire repo view
47	// --json` (entireio/cli#2758), which placement resolution depends on. Only
48	// connect's placement shell-out checks it: local-only brain use and explicit
49	// --repo-id/--api-url never touch the host CLI version. Empty disables the
50	// gate explicitly. A var so tests can exercise the gate.
51	var minHostCLIVersion = "0.11.6"
52	
53	// hostedPlacement is the slice of the host CLI's `entire repo view --json`
54	// output this plugin needs (entireio/cli#2758): the repo's region-local ULID
55	// and its cell API base URL, both top-level fields.
56	type hostedPlacement struct {
57		RepoID string `json:"repoId"`
58		APIURL string `json:"apiUrl"`
59	}
60	
61	type connectOptions struct {
62		repoID string
63		apiURL string
64	}
65	
66	func New(cfg Config) *cobra.Command {
67		var connectOpts connectOptions
68		cmd := &cobra.Command{
69			Use:   "connect",
70			Short: "Bind this repository to its hosted brain explicitly",
71			Long: `connect binds this repository to its hosted brain: it records the repo id and
72	API base URL (non-secrets only — the host CLI's own login mints a fresh token
73	per sync), then runs one immediate sync so the first pull happens right away.
74	
75	Running connect (or the onboarding flow) is the ONLY way a repository starts
76	syncing: by default memories stay local and background triggers never connect
77	a repo on their own. Placement resolves through the host CLI (entire repo
78	view); pass --repo-id and --api-url to bypass resolution — a non-default cell
79	or a staging target. Re-running connect re-joins after 'entire brain
80	disconnect'.`,
81			Args: cobra.NoArgs,
82			RunE: func(cmd *cobra.Command, args []string) error {
83				return runConnect(cmd, cfg, connectOpts)
84			},
85		}
86		cmd.Flags().StringVar(&connectOpts.repoID, "repo-id", "", "Hosted repo id (region-local ULID)")
87		cmd.Flags().StringVar(&connectOpts.apiURL, "api-url", "", "Entire API base URL, https://")
88		return cmd
89	}
90	
91	func runConnect(cmd *cobra.Command, cfg Config, connectOpts connectOptions) error {
92		ctx := cmd.Context()
93		opts := cfg.Options
94		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, cfg.Deps.AgentSurfaceTarget(opts, nil))
95		if err != nil {
96			return err
97		}
98		if !local {
99			return fmt.Errorf("connect requires a local repository path")
100		}
101		storage, err := cfg.Deps.RepoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
102		if err != nil {
103			return err
104		}
105	
106		repoID := strings.TrimSpace(connectOpts.repoID)
107		apiURL := strings.TrimSpace(connectOpts.apiURL)
108		if repoID == "" || apiURL == "" {
109			resolved, placementErr := resolveHostedPlacement(ctx, opts.Runner, repoDir)
110			if placementErr != nil {
111				// An already-connected (or disconnected — the opt-out keeps its
112				// coordinates) repo stays re-connectable without flags: re-connect
113				// means re-sync, not re-resolve.
114				if existing, present, readErr := brainstore.ReadHostedRepoBinding(storage.BrainDir); readErr == nil && present && existing.RepoID != "" {
115					resolved = hostedPlacement{RepoID: existing.RepoID, APIURL: existing.BaseURL}
116				} else {
117					// The hint sits on its own line: the host CLI's message ends
118					// with a newline of its own, so a "; pass ..." suffix used to
119					// dangle on a line starting with ";".
120					return fmt.Errorf("connect: %w\nOr pass --repo-id and --api-url explicitly", placementErr)
121				}
122			}
123			if repoID == "" {
124				repoID = resolved.RepoID
125			}
126			if apiURL == "" {
127				apiURL = resolved.APIURL
128			}
129		}
130		// Whether this run re-affirms an existing connection decides the success
131		// headline: "connected" must not read like a state change when nothing
132		// changed.
133		existing, existingPresent, existingErr := brainstore.ReadHostedRepoBinding(storage.BrainDir)
134		binding, err := bindHostedRepo(storage.BrainDir, repoID, apiURL)
135		if err != nil {
136			return fmt.Errorf("connect: %w", err)
137		}
138		already := existingErr == nil && existingPresent && !existing.OptedOut &&
139			existing.RepoID == binding.RepoID && existing.BaseURL == binding.BaseURL
140		// A connected repo wants the push-beat upload: install our pre-push hook
141		// (chained beside whatever hook owns the slot). Best-effort — a hook
142		// problem must not fail the connect.
143		if sharedHooksDir, hookPath, hookErr := cfg.Deps.InstallPushHook(ctx, opts, repoDir); hookErr != nil {
144			fmt.Fprintf(cmd.ErrOrStderr(), "connect: push hook not installed (uploads ride the daemon tick): %v\n", hookErr)
145		} else if sharedHooksDir {
146			fmt.Fprintf(cmd.ErrOrStderr(), "connect: core.hooksPath (%s) is shared across repos; push hook not managed — uploads ride the daemon tick\n", hookPath)
147		}
148		// The kill switch suppresses every sync this command is about to promise,
149		// so say that instead of "now syncing". The binding still gets recorded:
150		// the environment only subtracts, and unsetting it resumes syncing.
151		if base.BrainNoEgressMode() {
152			cmdutil.RenderHostedBanner(cmd.OutOrStdout(),
153				"Connected: "+storage.Key+" — but nothing syncs while "+base.NoEgressToggleName()+" is set",
154				"The binding is recorded and memories stay local. Unset "+base.NoEgressToggleName()+" to start syncing.")
155			return nil
156		}
157		// Connect doubles as the initial pull so a fresh clone receives team
158		// memories immediately. The sync runs BEFORE the banner so the headline
159		// reports what actually happened: a connect whose first pull failed has
160		// not started syncing, and claiming so hides a dead connection.
161		attempted, pullSucceeded, err := cfg.Deps.HostedFactsSyncAndPull(ctx, cmd.ErrOrStderr(), opts, repoDir, storage, cfg.Deps.HostedSyncBranch(ctx, opts.Runner, repoDir))
162		if err != nil {
163			return err
164		}
165		if !pullSucceeded {
166			verdict := "failed"
167			if !attempted {
168				verdict = "did not run"
169			}
170			return fmt.Errorf("connect: %s is bound, but the first sync %s (details above); memories stay local until a sync succeeds — fix the cause and re-run '%s'",
171				storage.Key, verdict, base.BrainInvocation(os.LookupEnv, "connect"))
172		}
173		headline := "Connected: " + storage.Key + " is now syncing memories"
174		if already {
175			headline = "Already connected: " + storage.Key + " — memories are syncing"
176		}
177		cmdutil.RenderHostedBanner(cmd.OutOrStdout(), headline,
178			"Memories sync periodically, at session end, and on git push. Teammates' memories merge into this repo's local brain.")
179		return nil
180	}
181	
182	// normalizeHostedBinding validates the target and strips a quoted /api/v1
183	// suffix. Cell URLs are commonly quoted with that prefix (repo view's apiUrl,
184	// docs examples), but the factsync client appends /api/v1/repos/... itself —
185	// storing the suffix would 404 every sync. OptedOut is false: a fresh binding
186	// is an opt-in.
187	func normalizeHostedBinding(repoID, apiURL string) (brainstore.HostedRepoBinding, error) {
188		if strings.TrimSpace(repoID) == "" {
189			return brainstore.HostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
190		}
191		validated, err := apiurl.Validate(apiURL)
192		if err != nil {
193			return brainstore.HostedRepoBinding{}, err
194		}
195		return brainstore.HostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}, nil
196	}
197	
198	// bindHostedRepo is the EXPLICIT connect write: it overwrites whatever is
199	// there, including an opt-out — running connect is how the user opts back in.
200	func bindHostedRepo(brainDir, repoID, apiURL string) (brainstore.HostedRepoBinding, error) {
201		binding, err := normalizeHostedBinding(repoID, apiURL)
202		if err != nil {
203			return brainstore.HostedRepoBinding{}, err
204		}
205		if err := brainstore.WriteHostedRepoBinding(brainDir, binding); err != nil {
206			return brainstore.HostedRepoBinding{}, err
207		}
208		return binding, nil
209	}
210	
211	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
212	// placement.
213	func resolveHostedPlacement(ctx context.Context, runner base.CommandRunner, repoDir string) (hostedPlacement, error) {
214		ctx, cancel := context.WithTimeout(ctx, base.HostedShellOutTimeout)
215		defer cancel()
216		if err := checkHostCLIVersion(ctx, runner, repoDir, minHostCLIVersion); err != nil {
217			return hostedPlacement{}, err
218		}
219		stdout, stderr, err := runner.Run(ctx, repoDir, base.HostEntireBinary, "repo", "view", "--json")
220		if err != nil {
221			return hostedPlacement{}, placementFailureError(err, stderr)
222		}
223		var result hostedPlacement
224		if err := base.DecodeHostCLIJSON(stdout, &result); err != nil {
225			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
226		}
227		return result, nil
228	}
229	
230	// placementFailureError reduces a failed `entire repo view --json` to the line
231	// the host CLI actually said. The runner's wrap carries debug framing — an
232	// argv echo plus the host's "Using context '…'." login banner — that a human
233	// reading connect's failure never needs. Drop the banner, then let
234	// providerdetail.Summary keep the host's Error:-marked or first stderr line.
235	func placementFailureError(runErr error, stderr []byte) error {
236		var kept []string
237		for _, line := range strings.Split(string(stderr), "\n") {
238			line = strings.TrimSpace(line)
239			if line == "" || strings.HasPrefix(line, "Using context ") {
240				continue
241			}
242			kept = append(kept, line)
243		}
244		if summary := providerdetail.Summary(strings.Join(kept, "\n")); summary != "" {
245			return errors.New(summary)
246		}
247		// Nothing usable on stderr: name the command and the cause under the
248		// runner's argv echo (exit status, or a missing host CLI).
249		cause := runErr
250		if unwrapped := errors.Unwrap(runErr); unwrapped != nil {
251			cause = unwrapped
252		}
253		return fmt.Errorf("`entire repo view --json`: %v", cause)
254	}
255	
256	// checkHostCLIVersion refuses placement resolution on a host CLI older than
257	// min, so the failure says "upgrade" instead of repo view's unknown-command
258	// noise. A missing CLI or an unrecognized version line (dev builds) passes:
259	// the repo view call itself is the authority on whether the command exists.
260	func checkHostCLIVersion(ctx context.Context, runner base.CommandRunner, repoDir, min string) error {
261		if min == "" {
262			return nil
263		}
264		stdout, _, err := runner.Run(ctx, repoDir, base.HostEntireBinary, "version")
265		if err != nil {
266			return nil
267		}
268		// First line is "Entire CLI <version>", on some builds with a trailing
269		// "(<commit>)". Take the first field that parses as semver, not a fixed
270		// position, so a build suffix cannot fail-open the gate.
271		line, _, _ := strings.Cut(strings.TrimSpace(string(stdout)), "\n")
272		got := ""
273		for _, field := range strings.Fields(line) {
274			if v := "v" + strings.TrimPrefix(field, "v"); semver.IsValid(v) {
275				got = v
276				break
277			}
278		}
279		if got == "" {
280			return nil
281		}
282		// Compare the release core only: a prerelease or pseudo-version of min
283		// (nightly, git describe) ranks below min in full semver order yet may
284		// already ship repo view — those builds pass and repo view stays the
285		// authority.
286		core := strings.TrimSuffix(got, semver.Build(got))
287		core = strings.TrimSuffix(core, semver.Prerelease(core))
288		if semver.Compare(core, "v"+min) >= 0 {
289			return nil
290		}
291		return fmt.Errorf("entire CLI %s does not support `entire repo view` (needs %s or newer); upgrade the entire CLI and re-run connect", strings.TrimPrefix(got, "v"), min)
292	}
