130	func newSessionsListCommand(opts Options) *cobra.Command {
131		var jsonOut bool
132		cmd := &cobra.Command{
133			Use:   "list",
134			Short: "List captured sessions and their exclusion state",
135			Args:  cobra.NoArgs,
136			RunE: func(cmd *cobra.Command, args []string) error {
137				storage, err := resolveSessionsBrain(cmd.Context(), opts)
138				if err != nil {
139					return err
140				}
141				brainDir := storage.BrainDir
142				manifest, err := bmanifest.Load(brainDir)
143				if err != nil {
144					return err
145				}
146				stones, _, err := brainstore.LoadSessionTombstonesChecked(brainDir)
147				if err != nil {
148					return err
149				}
150				var entries []sessionListEntry
151				if manifest.Sources != nil && manifest.Sources.Sessions != nil {
152					for _, session := range manifest.Sources.Sessions.Sessions {
153						entry := sessionListEntry{
154							SessionID: session.SessionID, Branch: session.Branch, Agent: session.Agent,
155							TranscriptPath: session.TranscriptPath,
156						}
157						if !session.CreatedAt.IsZero() {
158							entry.CreatedAt = session.CreatedAt.UTC().Format(time.RFC3339)
159						}
160						if stone, excluded := stones.Excluded[session.SessionID]; excluded {
161							entry.Excluded = true
162							entry.ExcludedAt = stone.At.UTC().Format(time.RFC3339)
163							entry.Reason = stone.Reason
164						}
165						entries = append(entries, entry)
166					}
167				}
168				sort.Slice(entries, func(i, j int) bool { return entries[i].CreatedAt > entries[j].CreatedAt })
169				// Tombstones for sessions no longer in the manifest still matter
170				// (they keep a re-export from re-indexing); list them too.
171				known := map[string]bool{}
172				for _, entry := range entries {
173					known[entry.SessionID] = true
174				}
175				for id, stone := range stones.Excluded {
176					if !known[id] {
177						entries = append(entries, sessionListEntry{SessionID: id, Excluded: true, Unmatched: true, ExcludedAt: stone.At.UTC().Format(time.RFC3339), Reason: stone.Reason})
178					}
179				}
180				if jsonOut {
181					if entries == nil {
182						entries = []sessionListEntry{}
183					}
184					return cmdutil.WriteJSON(cmd, map[string]any{"sessions": entries})
185				}
186				return cmdutil.WriteText(cmd, func(out io.Writer) {
187					// An empty session list is the normal state of a brain that has
188					// never captured a session, and printing nothing for it made the
189					// one command a privacy-conscious user reaches for indistinguishable
190					// from a command that failed to look. Say which it is.
191					if len(entries) == 0 {
192						fmt.Fprintln(out, "no captured sessions in this brain")
193						return
194					}
195					unmatched := 0
196					for _, entry := range entries {
197						state := "included"
198						switch {
199						case entry.Excluded && entry.Unmatched:
200							// Distinct from EXCLUDED on purpose. The row is the
201							// only place a user can notice that the id they typed
202							// matched nothing -- every other column is <unset>,
203							// which reads as missing metadata rather than as a
204							// tombstone waiting for a session that may never exist.
205							state = "UNMATCHED"
206							unmatched++
207						case entry.Excluded:
208							state = "EXCLUDED"
209						}
210						fmt.Fprintf(out, "%-10s %s  %s  %s  %s\n", state, valueOrUnset(entry.SessionID), valueOrUnset(entry.CreatedAt), valueOrUnset(entry.Agent), entry.TranscriptPath)
211					}
212					if unmatched > 0 {
213						fmt.Fprintf(out, "UNMATCHED: %d tombstone(s) match no captured session in this brain; each stays recorded and applies if such a session is captured later\n", unmatched)
214					}
215				})
216			},
217		}
218		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
